    /// <summary>§9.1 语义：仅当有限值时与阈值比较；IsTop ⇒ 视为需人工界定返回 false（不报警）。</summary>
    public bool ExceedsThreshold(double threshold) => !IsTop && Value > threshold;

    public override string ToString() => IsTop ? "⊤" : Value.ToString("P");
}

