namespace Cosmos.EffectAlgebra;

/// <summary>
/// §3.3.1 — 有符号网值 ℤ* = ℤ ∪ {⊤}。net = Σcreate c.size − Σrelease c.size 可为负（ℕ* 无法表达）。
/// ⊤ 仍为上界标记（未知/不可闭合网），永不 NaN/发散。
/// 有符号边界由 <see cref="ZStar"/> 类型强制（Lo/Hi 为 ZStar，符号由 long 存值表达），非运行时 if 漏判。
/// </summary>
public readonly record struct ZStar
{
    /// <summary>true ⇒ 上界未知/不可闭合；<see cref="Value"/> 无效。</summary>
    public bool IsTop { get; }

    /// <summary>仅当 !IsTop 有效（可正可负）。</summary>
    public long Value { get; }

    private ZStar(bool isTop, long value) { IsTop = isTop; Value = value; }

    /// <summary>上界标记 ⊤。</summary>
    public static readonly ZStar Top = new(true, 0);

    /// <summary>从具体整数构造。</summary>
    public static ZStar Of(long v) => new(false, v);

    // §3.3.1 加法律：任一 IsTop ⇒ Top
    public static ZStar operator +(ZStar a, ZStar b) => (a.IsTop || b.IsTop) ? Top : Of(a.Value + b.Value);

    // §3.3.1 减法律：任一 IsTop ⇒ Top
    public static ZStar operator -(ZStar a, ZStar b) => (a.IsTop || b.IsTop) ? Top : Of(a.Value - b.Value);

    // §3.3.1 一元负：⊤ ⇒ Top
    public static ZStar operator -(ZStar a) => a.IsTop ? Top : Of(-a.Value);

    // §3.3.1a ⊤ 律（与 §3.1.5a 同半格）：min(x,⊤)=x；max(x,⊤)=⊤
    public ZStar Min(ZStar o) => (IsTop || o.IsTop) ? (IsTop ? o : this) : Of(Math.Min(Value, o.Value));

    public ZStar Max(ZStar o) => (IsTop || o.IsTop) ? Top : Of(Math.Max(Value, o.Value));

    public override string ToString() => IsTop ? "⊤" : Value.ToString();
}

/// <summary>
/// §3.3.1 — 有符号网区间 [Lo, Hi]（Lo,Hi ∈ ℤ*）。create/release 抵消后净效应区间；
/// ContainsZero=true ⇔ Lo≤0≤Hi ⇔ 该资源生命周期可能闭合（DO-9 不报警）。
/// 下界不可大于上界（Lo>Hi 非 ⊤ 时抛 ArgumentException，§3.3.1 不变量）。
/// </summary>
public readonly record struct SignedInterval
{
    public ZStar Lo { get; }
    public ZStar Hi { get; }

    public SignedInterval(ZStar lo, ZStar hi)
    {
        // 仅当双侧有限时校验 lo≤hi；任一 ⊤ ⇒ 跳过（未知上界，合法）
        if (!lo.IsTop && !hi.IsTop && lo.Value > hi.Value)
            throw new ArgumentException($"SignedInterval lo({lo}) > hi({hi}) violates §3.3.1 lo≤hi");
        Lo = lo;
        Hi = hi;
    }

    /// <summary>§3.3.1 — 零区间 [0,0]（create/release 平衡 ⇒ ContainsZero=true）。</summary>
    public static readonly SignedInterval Zero = new(ZStar.Of(0), ZStar.Of(0));

    /// <summary>§3.3.1 — 区间含 0 ⇔ Lo≤0≤Hi；任一 ⊤ ⇒ false（未知 ⇒ 不宣称闭合，fail-closed）。</summary>
    public bool ContainsZero => !Lo.IsTop && !Hi.IsTop && Lo.Value <= 0 && Hi.Value >= 0;

    /// <summary>§3.3.1 merge（join 半格）：min 取 Lo、max 取 Hi，内嵌 ZStar ⊤ 律。</summary>
    public SignedInterval Merge(SignedInterval o) => new(Lo.Min(o.Lo), Hi.Max(o.Hi));

    public override string ToString() => $"[{Lo},{Hi}]";
}
