        var lo = s.Lo.IsTop ? ZStar.Top : ZStar.Of((long)s.Lo.Value);
        var hi = s.Hi.IsTop ? ZStar.Top : ZStar.Of((long)s.Hi.Value);
        return new SignedInterval(lo, hi);
    }

